<?php

declare(strict_types=1);

namespace App\Modules\Expert\Editorial;

use App\Modules\Expert\Domain\Enums\QuestionTopic;

/**
 * پرسش و پاسخ‌های نمونه تحریریه فرابهداشت، سه تا برای هر حوزه.
 *
 * هر عدد یا قاعده‌ای که در پاسخ آمده باید در منابع همان پاسخ باشد. پاسخ‌ها
 * ادعای انطباق قانونی قطعی یا تشخیص پزشکی ندارند و هشدار عمومی زیر هر پاسخ
 * همچنان نمایش داده می‌شود. ترتیب این فهرست ترتیب صفحه «پرسش از متخصص» است.
 */
final readonly class EditorialQuestions
{
    /** @return list<EditorialEntry> */
    public function entries(): array
    {
        return [...$this->noise(), ...$this->heat(), ...$this->chemical(), ...$this->ventilation(), ...$this->lighting(),
            ...$this->vibration(), ...$this->ergonomics(), ...$this->statistics(), ...$this->management(), ...$this->other()];
    }

    /** @return list<EditorialEntry> */
    private function noise(): array
    {
        return [
            new EditorialEntry(
                key: 'noise-combining-sources',
                topic: QuestionTopic::Noise,
                title: 'دو دستگاه هرکدام ۸۵ دسی‌بل؛ تراز کل سالن چقدر می‌شود؟',
                question: 'در سالن تولید دو دستگاه داریم که هرکدام به‌تنهایی در محل کار اپراتور حدود ۸۵ دسی‌بل A تولید می‌کنند. وقتی هر دو روشن‌اند، تراز صدا را چطور حساب کنیم؟ جمع ساده دو عدد درست است؟',
                answer: [
                    'نه. تراز صدا لگاریتمی است و جمع حسابی نمی‌شود. برای ترکیب چند منبع، هر تراز را به انرژی برمی‌گردانیم، انرژی‌ها را جمع می‌زنیم و دوباره به دسی‌بل می‌بریم: تراز کل برابر است با ده ضرب در لگاریتم مجموع «۱۰ به توان تراز هر منبع تقسیم بر ۱۰».',
                    'برای دو منبع هم‌تراز ۸۵ دسی‌بل نتیجه حدود ۸۸ دسی‌بل است؛ دو برابر شدن انرژی صوت فقط ۳ دسی‌بل به تراز اضافه می‌کند. اگر اختلاف دو منبع ۱۰ دسی‌بل یا بیشتر باشد، منبع ضعیف‌تر کمتر از نیم دسی‌بل اثر دارد. همین نکته اولویت کنترل را هم روشن می‌کند: تا بلندترین منبع کنترل نشود، کار روی منبع‌های ضعیف‌تر تغییر محسوسی در تراز کل نمی‌دهد.',
                    'این محاسبه برای برآورد و اولویت‌بندی است. آنچه با حد مجاز مقایسه می‌شود تراز مواجهه روزانه شاغل (LEX,8h) است که باید با روش استاندارد اندازه‌گیری شود، نه جمع تراز منبع‌ها. ابزار «جمع ترازهای صوتی» فرابهداشت همین محاسبه را انجام می‌دهد.',
                ],
                sources: ['ISO 9612:2009 — Determination of occupational noise exposure', 'حدود مجاز مواجهه شغلی، وزارت بهداشت، درمان و آموزش پزشکی'],
            ),
            new EditorialEntry(
                key: 'noise-exchange-rate-duration',
                topic: QuestionTopic::Noise,
                title: 'با تراز ۹۱ دسی‌بل چند ساعت مواجهه مجاز است؟',
                question: 'تراز صدای یک ایستگاه کاری ۹۱ دسی‌بل A اندازه‌گیری شده و شاغل تمام شیفت هشت‌ساعته آنجاست. حد مجاز ۸۵ دسی‌بل است؛ مدت مجاز مواجهه با ۹۱ دسی‌بل چقدر است و چرا عدد OSHA با عدد ایران فرق دارد؟',
                answer: [
                    'در حدود مجاز مواجهه شغلی ایران، مانند توصیه ACGIH و NIOSH، حد مواجهه هشت‌ساعته ۸۵ دسی‌بل A با نرخ تبادل ۳ دسی‌بل است: با هر ۳ دسی‌بل افزایش تراز، مدت مجاز نصف می‌شود. پس ۸۵ دسی‌بل هشت ساعت، ۸۸ دسی‌بل چهار ساعت و ۹۱ دسی‌بل دو ساعت. فرمول کلی: مدت مجاز به ساعت برابر است با ۸ تقسیم بر «۲ به توان (تراز منهای ۸۵) تقسیم بر ۳».',
                    'با این حساب، شاغلی که هشت ساعت در ۹۱ دسی‌بل کار می‌کند چهار برابر دوز مجاز (۴۰۰ درصد) دریافت می‌کند. ترتیب اقدام: کنترل فنی منبع و مسیر انتشار، بعد کاهش زمان مواجهه، و در کنار آنها حفاظ شنوایی مناسب و برنامه حفاظت شنوایی با ادیومتری دوره‌ای.',
                    'OSHA آمریکا حد قانونی خود را ۹۰ دسی‌بل A با نرخ تبادل ۵ دسی‌بل گذاشته و ۸۵ دسی‌بل را «سطح اقدام» برنامه حفاظت شنوایی می‌داند. این حد قدیمی‌تر و کم‌حفاظت‌تر است و NIOSH هم ۸۵ دسی‌بل با نرخ ۳ دسی‌بل را توصیه می‌کند. در ایران ملاک، حدود مجاز وزارت بهداشت است.',
                    'دقت کنید عدد ۹۱ باید تراز معادل در طول شیفت باشد، نه یک قرائت لحظه‌ای. اگر تراز در طول شیفت تغییر می‌کند، دوز را از جمع سهم هر بازه حساب کنید؛ ابزار «دز صدا» برای همین است.',
                ],
                sources: ['حدود مجاز مواجهه شغلی، وزارت بهداشت، درمان و آموزش پزشکی', 'NIOSH Criteria for a Recommended Standard: Occupational Noise Exposure (1998)', 'OSHA 29 CFR 1910.95'],
            ),
            new EditorialEntry(
                key: 'noise-hearing-protector-nrr',
                topic: QuestionTopic::Noise,
                title: 'گوشی با NRR برابر ۲۹ در عمل چقدر صدا را کم می‌کند؟',
                question: 'تراز مواجهه هشت‌ساعته ۹۸ دسی‌بل A اندازه گرفته‌ایم. روی بسته ایرپلاگ نوشته NRR ۲۹. یعنی تراز مؤثر در گوش کارگر ۶۹ دسی‌بل می‌شود؟',
                answer: [
                    'نه. NRR در آزمایشگاه و با جای‌گذاری ایده‌آل به دست می‌آید و نسبت به تراز با وزن C تعریف شده است. برای استفاده درست دو اصلاح لازم است.',
                    'اول، اگر تراز با وزن A اندازه‌گیری شده، طبق پیوست B استاندارد صدای OSHA ابتدا ۷ دسی‌بل از NRR کم می‌شود. دوم، برای فاصله آزمایشگاه تا کارگاه کاهش اضافه لازم است: OSHA در راهنمای فنی خود نصف کردن عدد اصلاح‌شده را پیشنهاد می‌کند و NIOSH کم کردن ۲۵ درصد برای گوشی رو گوشی، ۵۰ درصد برای ایرپلاگ فومی و ۷۰ درصد برای سایر ایرپلاگ‌ها را.',
                    'با روش OSHA برای مثال شما: ۲۹ منهای ۷ می‌شود ۲۲ و نصف آن ۱۱ دسی‌بل؛ تراز مؤثر حدود ۸۷ دسی‌بل A است، یعنی هنوز بالاتر از ۸۵. پس این حفاظ به‌تنهایی کافی نیست و باید حفاظ قوی‌تر، حفاظ دوگانه (ایرپلاگ همراه گوشی رو گوشی) و مهم‌تر از همه کنترل فنی منبع بررسی شود.',
                    'حفاظت بیش از حد هم مشکل است: اگر تراز زیر حفاظ خیلی پایین بیاید، شاغل صدای هشدار و همکار را نمی‌شنود و حفاظ را برمی‌دارد. HSE انگلستان رساندن تراز در گوش به حدود ۷۰ تا ۸۰ دسی‌بل را هدف می‌داند. آموزش جای‌گذاری درست و آزمون برازش فردی بیشترین اثر را بر حفاظت واقعی دارد.',
                ],
                sources: ['OSHA 29 CFR 1910.95 Appendix B', 'OSHA Technical Manual, Section III Chapter 5 — Noise', 'NIOSH Criteria for a Recommended Standard: Occupational Noise Exposure (1998)', 'HSE L108 — Controlling noise at work'],
            ),
        ];
    }

    /** @return list<EditorialEntry> */
    private function heat(): array
    {
        return [
            new EditorialEntry(
                key: 'heat-wbgt-indoor-outdoor',
                topic: QuestionTopic::Heat,
                title: 'فرمول WBGT در فضای باز و سالن سرپوشیده چه فرقی دارد؟',
                question: 'برای پایش گرما هم در سالن ریخته‌گری و هم در محوطه بارگیری زیر آفتاب اندازه‌گیری داریم. فرمول WBGT برای این دو یکی است؟ سالن ریخته‌گری که تابش کوره دارد جزو کدام است؟',
                answer: [
                    'دو فرمول دارد. در محیط بسته یا بیرون بدون تابش مستقیم خورشید: WBGT برابر ۰٫۷ ضرب در دمای تر طبیعی به‌اضافه ۰٫۳ ضرب در دمای گویسان. در بیرون زیر تابش خورشید: ۰٫۷ ضرب در دمای تر طبیعی به‌اضافه ۰٫۲ ضرب در دمای گویسان به‌اضافه ۰٫۱ ضرب در دمای خشک هوا.',
                    'سالن ریخته‌گری با وجود تابش شدید کوره «بدون تابش خورشید» حساب می‌شود؛ فرمول دوم فقط برای تابش خورشید است و اثر تابش کوره را دماسنج گویسان می‌گیرد. بیشترین وزن در هر دو فرمول با دمای تر طبیعی است، پس فتیله باید تمیز و با آب مقطر خیس باشد و گویسان پیش از قرائت به تعادل برسد.',
                    'اگر گرما در ارتفاع بدن یکنواخت نیست، ISO 7243 اندازه‌گیری در سه ارتفاع سر، شکم و مچ پا و میانگین وزنی با وزن ۱، ۲ و ۱ تقسیم بر ۴ را می‌خواهد. عدد WBGT به‌تنهایی برای قضاوت کافی نیست؛ باید با بار متابولیکی کار، نوع لباس و برنامه کار و استراحت کنار هم دیده شود. دو ابزار «شاخص WBGT» فرابهداشت هر دو فرمول را دارند.',
                ],
                sources: ['ISO 7243:2017 — Assessment of heat stress using the WBGT index', 'ACGIH TLVs and BEIs — Heat Stress and Strain', 'حدود مجاز مواجهه شغلی، وزارت بهداشت، درمان و آموزش پزشکی'],
            ),
            new EditorialEntry(
                key: 'heat-acclimatization',
                topic: QuestionTopic::Heat,
                title: 'کارگر تازه‌وارد در سالن گرم را چطور با گرما سازگار کنیم؟',
                question: 'چند کارگر جدید برای تابستان به سالن کوره آمده‌اند. شنیده‌ام بیشتر حوادث گرمایی در روزهای اول کار رخ می‌دهد. برنامه سازگاری با گرما باید چطور باشد؟',
                answer: [
                    'درست شنیده‌اید؛ OSHA گزارش کرده که بین ۵۰ تا ۷۰ درصد مرگ‌های ناشی از گرما در کار بیرون، در چند روز اول کار در محیط گرم رخ داده است. بدن طی حدود ۷ تا ۱۴ روز با گرما سازگار می‌شود و این دوره باید برنامه‌ریزی‌شده باشد.',
                    'NIOSH برای کارگر تازه‌کار پیشنهاد می‌کند روز اول بیش از ۲۰ درصد مدت مواجهه معمول را در گرما نگذراند و هر روز بیش از ۲۰ درصد به آن اضافه نشود. برای کارگر باتجربه‌ای که به این کار برگشته: روز اول ۵۰ درصد، روز دوم ۶۰ درصد، روز سوم ۸۰ درصد و از روز چهارم ۱۰۰ درصد.',
                    'سازگاری با دوری از گرما (مرخصی، بیماری) کم می‌شود؛ برای برگشتی‌ها برنامه را دوباره اجرا کنید. در روزهای اول شاغل را تنها نگذارید، علائم بیماری‌های گرمایی را به او و سرپرستش آموزش دهید و آب خنک در دسترس باشد. برنامه سازگاری مکمل کنترل فنی مثل سپر تابشی و تهویه است، نه جایگزین آن.',
                ],
                sources: ['NIOSH Criteria for a Recommended Standard: Occupational Exposure to Heat and Hot Environments, DHHS (NIOSH) 2016-106', 'OSHA — Heat Illness Prevention: Protecting New Workers'],
            ),
            new EditorialEntry(
                key: 'heat-water-intake',
                topic: QuestionTopic::Heat,
                title: 'کارگر در محیط گرم چقدر آب بنوشد؟',
                question: 'در محیط گرم به کارگران گفته‌ایم هر وقت تشنه شدند آب بخورند. این کافی است یا مقدار مشخصی توصیه شده؟',
                answer: [
                    'تشنگی نشانه دیرهنگام کم‌آبی است و در کار سنگین در گرما معمولاً کافی نیست. NIOSH برای کار متوسط در شرایط گرم متوسط نوشیدن حدود یک لیوان (۲۳۷ میلی‌لیتر) آب خنک هر ۱۵ تا ۲۰ دقیقه را توصیه می‌کند، حتی اگر شاغل تشنه نباشد. نوشیدن کم و پیوسته از نوشیدن مقدار زیاد در یک نوبت بهتر است.',
                    'حد بالا هم مهم است: NIOSH توصیه می‌کند بیش از حدود ۱٫۴ لیتر در ساعت نوشیده نشود، چون نوشیدن بیش از حد آب ساده می‌تواند سدیم خون را به‌طور خطرناکی پایین بیاورد. در تعریق شدید چندساعته، نوشیدنی دارای الکترولیت مناسب است. نوشیدنی‌های انرژی‌زا و پرکافئین جایگزین آب نیستند.',
                    'برای عملی شدن، آب خنک و تمیز نزدیک محل کار باشد، زمان استراحت در جای خنک در برنامه شیفت بیاید و علائم هشدار مثل سردرد، سرگیجه و تهوع به شاغلان آموزش داده شود.',
                ],
                sources: ['NIOSH Criteria for a Recommended Standard: Occupational Exposure to Heat and Hot Environments, DHHS (NIOSH) 2016-106'],
            ),
        ];
    }

    /** @return list<EditorialEntry> */
    private function chemical(): array
    {
        return [
            new EditorialEntry(
                key: 'chemical-twa-calculation',
                topic: QuestionTopic::Chemical,
                title: 'میانگین وزنی-زمانی (TWA) را از چند نمونه چطور حساب کنیم؟',
                question: 'برای تولوئن در طول شیفت این نتایج را داریم: سه ساعت ۵۰ ppm، چهار ساعت ۲۰ ppm و یک ساعت شاغل در محلی بدون مواجهه بوده. TWA هشت‌ساعته چقدر است؟',
                answer: [
                    'TWA هشت‌ساعته برابر است با مجموع «غلظت هر بازه ضرب در مدت آن» تقسیم بر ۸ ساعت. بازه بدون مواجهه با غلظت صفر وارد می‌شود، به شرطی که واقعاً مواجهه‌ای نبوده باشد.',
                    'برای مثال شما: ۵۰ ضرب در ۳ به‌اضافه ۲۰ ضرب در ۴ به‌اضافه صفر ضرب در ۱ می‌شود ۲۳۰ ppm-ساعت؛ تقسیم بر ۸ حدود ۲۸٫۸ ppm.',
                    'این عدد را با حد مجاز TWA همان ماده مقایسه کنید. حد مجاز تولوئن در ACGIH برابر ۲۰ ppm است؛ عدد جدول حدود مجاز ایران را هم برای همان سال ببینید. در این مثال TWA بیش از ۲۰ است. تولوئن در ACGIH حد کوتاه‌مدت (STEL) ندارد؛ برای چنین موادی ACGIH توصیه می‌کند غلظت بیش از ۳ برابر حد TWA روی هم بیش از ۳۰ دقیقه در شیفت نباشد و هرگز از ۵ برابر بیشتر نشود.',
                    'دو نکته رایج: اگر شیفت بیش از هشت ساعت است، حد مجاز را با مدلی مثل بریف و اسکالا تعدیل کنید؛ و اگر بخشی از شیفت نمونه‌برداری نشده، فرض صفر برای آن بدون دلیل محکم، مواجهه را کمتر از واقع نشان می‌دهد. ابزار «میانگین وزنی-زمانی (ppm)» فرابهداشت همین محاسبه را با بازه‌های شما انجام می‌دهد.',
                ],
                sources: ['OSHA 29 CFR 1910.1000(d)', 'ACGIH TLVs and BEIs — Toluene; Excursion Limits', 'NIOSH Occupational Exposure Sampling Strategy Manual (1977)'],
            ),
            new EditorialEntry(
                key: 'chemical-mixture-additive',
                topic: QuestionTopic::Chemical,
                title: 'مواجهه هم‌زمان با چند حلال را چطور ارزیابی کنیم؟',
                question: 'در سالن رنگ‌کاری تولوئن، زایلن و استون هم‌زمان در هوا هست و غلظت هرکدام زیر حد مجاز خودش است. یعنی وضعیت قابل قبول است؟',
                answer: [
                    'لزوماً نه. وقتی چند ماده اثر مشابه بر یک اندام هدف دارند، مثلاً حلال‌های آلی که هرکدام بر دستگاه عصبی مرکزی اثر می‌گذارند، ACGIH و OSHA اثر آنها را جمع‌پذیر فرض می‌کنند. شاخص مواجهه مخلوط برابر است با مجموع «غلظت هر ماده تقسیم بر حد مجاز همان ماده». اگر این مجموع از ۱ بیشتر شود، حد مجاز مخلوط رد شده است، حتی اگر هر ماده به‌تنهایی زیر حد خود باشد.',
                    'مثال: اگر نسبت غلظت به حد مجاز برای این سه حلال ۰٫۶، ۰٫۵ و ۰٫۴ باشد، هر سه زیر ۱ هستند ولی مجموع ۱٫۵ است؛ یعنی مخلوط بیش از حد مجاز است.',
                    'این قاعده برای موادی است که اثر مشابه دارند. برای موادی با اثر مستقل بر اندام‌های متفاوت، هر ماده جدا سنجیده می‌شود. اگر درباره مشابه بودن اثر شک دارید، فرض محافظه‌کارانه جمع‌پذیری است. ابزار «شاخص مواجهه با مخلوط» فرابهداشت این مجموع را حساب می‌کند.',
                ],
                sources: ['ACGIH TLVs and BEIs — Appendix E: Threshold Limit Values for Mixtures', 'OSHA 29 CFR 1910.1000(d)(2)'],
            ),
            new EditorialEntry(
                key: 'chemical-ppm-to-mgm3',
                topic: QuestionTopic::Chemical,
                title: 'تبدیل ppm به میلی‌گرم بر مترمکعب چطور انجام می‌شود؟',
                question: 'حد مجاز یک بخار در جدول بر حسب ppm است ولی نتیجه آزمایشگاه بر حسب میلی‌گرم بر مترمکعب آمده. چطور این دو را تبدیل کنم؟',
                answer: [
                    'برای گاز و بخار در دمای ۲۵ درجه سلسیوس و فشار یک اتمسفر: غلظت جرمی به میلی‌گرم بر مترمکعب برابر است با ppm ضرب در جرم مولکولی (گرم بر مول) تقسیم بر ۲۴٫۴۵. عدد ۲۴٫۴۵ حجم یک مول گاز ایده‌آل به لیتر در همین شرایط است. برعکس: ppm برابر است با میلی‌گرم بر مترمکعب ضرب در ۲۴٫۴۵ تقسیم بر جرم مولکولی.',
                    'مثال: تولوئن جرم مولکولی ۹۲٫۱۴ دارد؛ ۲۰ ppm تولوئن حدود ۷۵٫۴ میلی‌گرم بر مترمکعب است.',
                    'حدود مجاز ACGIH برای همین شرایط مرجع، ۲۵ درجه و ۷۶۰ میلی‌متر جیوه، بیان شده‌اند. در دما و فشار دیگر حجم مولی تغییر می‌کند: ۲۲٫۴۱ ضرب در «دمای مطلق تقسیم بر ۲۷۳٫۱۵» ضرب در «۷۶۰ تقسیم بر فشار به میلی‌متر جیوه». این تبدیل فقط برای گاز و بخار معنی دارد؛ حد مجاز گرد و غبار، فیوم و مه فقط بر حسب جرم است. ابزار «تبدیل ppm به mg/m³» فرابهداشت دما و فشار را هم می‌گیرد.',
                ],
                sources: ['ACGIH TLVs and BEIs — Introduction to the Chemical Substances', 'NIOSH Pocket Guide to Chemical Hazards'],
            ),
        ];
    }

    /** @return list<EditorialEntry> */
    private function ventilation(): array
    {
        return [
            new EditorialEntry(
                key: 'ventilation-capture-velocity',
                topic: QuestionTopic::Ventilation,
                title: 'سرعت گیرش هود موضعی را چقدر در نظر بگیریم؟',
                question: 'برای یک میز جوشکاری و یک مخزن چربی‌زدایی هود موضعی طراحی می‌کنیم. سرعت گیرش (capture velocity) را چند متر بر ثانیه بگیریم؟',
                answer: [
                    'بسته به نحوه انتشار آلاینده و جریان هوای مزاحم. دامنه‌های راهنمای تهویه صنعتی ACGIH: انتشار تقریباً بدون سرعت در هوای آرام، مثل تبخیر از مخزن یا چربی‌زدایی، ۰٫۲۵ تا ۰٫۵ متر بر ثانیه؛ انتشار با سرعت کم در هوای نسبتاً آرام، مثل جوشکاری، ۰٫۵ تا ۱؛ تولید فعال در هوای پرجریان، مثل پاشش رنگ در کابین کم‌عمق، ۱ تا ۲٫۵؛ و انتشار با سرعت اولیه زیاد، مثل سنگ‌زنی و سندبلاست، ۲٫۵ تا ۱۰ متر بر ثانیه.',
                    'انتخاب سر پایین یا بالای هر دامنه به جریان هوای مزاحم، سمیت ماده، مقدار تولید و اندازه هود بستگی دارد. سرعت گیرش در محل انتشار تعریف می‌شود، نه در دهانه هود، و با فاصله به‌سرعت افت می‌کند.',
                    'برای هود ساده بدون فلنج، رابطه دالاواله دبی لازم را برابر سرعت گیرش ضرب در «۱۰ برابر مجذور فاصله به‌اضافه مساحت دهانه» می‌دهد و فلنج حدود ۲۵ درصد دبی را کم می‌کند. یعنی اگر فاصله منبع از هود دو برابر شود، دبی لازم تقریباً چهار برابر می‌شود. پس هود را تا جای ممکن نزدیک منبع بگذارید و پس از نصب، سرعت را در محل منبع اندازه بگیرید.',
                ],
                sources: ['ACGIH Industrial Ventilation: A Manual of Recommended Practice for Design'],
            ),
            new EditorialEntry(
                key: 'ventilation-duct-velocity',
                topic: QuestionTopic::Ventilation,
                title: 'چرا کانال مکش گرد و غبار مرتب گرفته می‌شود؟',
                question: 'در سیستم مکش گرد و غبار یک سنگ‌بری، کانال‌ها مرتب گرفته می‌شوند. سرعت هوا در کانال باید چقدر باشد؟',
                answer: [
                    'گرفتگی کانال معمولاً نشانه سرعت انتقال کمتر از حد لازم است؛ ذرات ته‌نشین می‌شوند و کم‌کم مقطع را می‌بندند. راهنمای تهویه صنعتی ACGIH این سرعت‌های کمینه را توصیه می‌کند: فیوم حدود ۱۰ تا ۱۲٫۵ متر بر ثانیه، گرد و غبار خیلی ریز و سبک ۱۲٫۵ تا ۱۵، گرد و غبار خشک و پودر ۱۵ تا ۲۰، گرد و غبار معمول صنعتی از جمله گرد سنگ و سیلیس حدود ۱۷٫۵ تا ۲۰، و گرد و غبار سنگین ۲۰ تا ۲۲٫۵ متر بر ثانیه و برای سنگین یا مرطوب بیشتر.',
                    'دلایل رایج افت سرعت: اضافه کردن انشعاب بدون بازطراحی، دریچه‌های بی‌استفاده باز، نشتی کانال، فیلتر کیسه‌ای پر و شل بودن تسمه فن. اندازه‌گیری سرعت در کانال و فشار استاتیک هر هود و مقایسه با مقدار مبنای پس از راه‌اندازی، معمولاً محل مشکل را نشان می‌دهد.',
                    'سرعت خیلی بیش از نیاز هم خوب نیست: سایش کانال، مصرف انرژی و صدای سیستم بالا می‌رود. زانویی با شعاع بزرگ و اتصال انشعاب با زاویه کم به کانال اصلی هم از ته‌نشینی و افت فشار می‌کاهد.',
                ],
                sources: ['ACGIH Industrial Ventilation: A Manual of Recommended Practice for Design — Minimum duct design velocities'],
            ),
            new EditorialEntry(
                key: 'ventilation-dilution-vs-local',
                topic: QuestionTopic::Ventilation,
                title: 'فن دیواری کافی است یا تهویه موضعی لازم است؟',
                question: 'در یک کارگاه کوچک که قطعات را با حلال تمیز می‌کنند، چند فن دیواری نصب کرده‌ایم. آیا این کار به‌جای هود موضعی کافی است؟',
                answer: [
                    'معمولاً نه. تهویه عمومی (رقیق‌سازی) آلاینده را پس از پخش شدن در هوای کارگاه رقیق می‌کند؛ تهویه موضعی آن را در محل تولید و پیش از رسیدن به ناحیه تنفس شاغل می‌گیرد. ACGIH تهویه رقیق‌سازی را فقط وقتی مناسب می‌داند که سمیت ماده کم، مقدار تولید کم و نسبتاً یکنواخت، شاغل به اندازه کافی از منبع دور و منابع پراکنده باشند. تمیزکاری با حلال کنار دست شاغل معمولاً این شرایط را ندارد.',
                    'دبی لازم برای رقیق‌سازی با نرخ تولید آلاینده و ضریب اختلاط ناقص (معمولاً ۳ تا ۱۰) متناسب است و با حد مجاز نسبت عکس دارد؛ برای مواد با حد مجاز پایین، دبی لازم غیرعملی می‌شود. «تعداد تعویض هوا در ساعت» به‌تنهایی معیار طراحی نیست، چون به نرخ تولید آلاینده ربطی ندارد.',
                    'جای فن‌ها هم مهم است: هوای تازه از پشت شاغل وارد و از سمت منبع، دور از ناحیه تنفس، خارج شود و هوای جبرانی کافی وجود داشته باشد؛ بدون آن فن‌ها دبی اسمی را نمی‌دهند. پاسخ نهایی را اندازه‌گیری مواجهه در ناحیه تنفس شاغل می‌دهد. ابزار «دبی لازم برای تهویه رقیق‌سازی» فرابهداشت برآورد اولیه را می‌دهد.',
                ],
                sources: ['ACGIH Industrial Ventilation: A Manual of Recommended Practice for Design — General Industrial Ventilation'],
            ),
        ];
    }

    /** @return list<EditorialEntry> */
    private function lighting(): array
    {
        return [
            new EditorialEntry(
                key: 'lighting-office-illuminance',
                topic: QuestionTopic::Lighting,
                title: 'روشنایی میز کار اداری چند لوکس باشد؟',
                question: 'در یک اداره روی میزها بین ۱۸۰ تا ۲۵۰ لوکس اندازه گرفته‌ایم. کارکنان با رایانه کار می‌کنند و سند کاغذی هم می‌خوانند. این مقدار کافی است؟',
                answer: [
                    'برای نوشتن، تایپ، خواندن و کار با رایانه، استاندارد ISO 8995-1 روشنایی متوسط نگه‌داشته‌شده ۵۰۰ لوکس را روی سطح کار توصیه می‌کند. ۱۸۰ تا ۲۵۰ لوکس برای این کار کم است. برای مقایسه، همین استاندارد برای راهرو ۱۰۰ و برای بایگانی ۲۰۰ لوکس را کافی می‌داند.',
                    '«نگه‌داشته‌شده» یعنی مقداری که در طول عمر سیستم نباید پایین‌تر برود؛ پس کثیف شدن چراغ و افت نور لامپ را از پیش در نظر بگیرید. یکنواختی هم مهم است: ISO 8995-1 نسبت کمینه به میانگین را در ناحیه کار دست‌کم ۰٫۷ و در پیرامون نزدیک آن دست‌کم ۰٫۵ می‌خواهد.',
                    'پیش از افزودن چراغ، چیدمان میزها نسبت به چراغ و پنجره و تمیزی و سلامت چراغ‌ها را بررسی کنید. افزایش روشنایی بدون کنترل خیرگی می‌تواند بازتاب روی صفحه نمایش را بدتر کند؛ برای دفتر کار، شاخص خیرگی UGR حداکثر ۱۹ توصیه شده است. ابزار «روشنایی متوسط و یکنواختی» فرابهداشت هر دو عدد را از نتایج شبکه اندازه‌گیری حساب می‌کند.',
                ],
                sources: ['ISO 8995-1:2002 (CIE S 008/E) — Lighting of work places: Indoor'],
            ),
            new EditorialEntry(
                key: 'lighting-measurement-grid',
                topic: QuestionTopic::Lighting,
                title: 'روشنایی سالن را در چند نقطه و در چه ارتفاعی اندازه بگیریم؟',
                question: 'می‌خواهیم روشنایی عمومی یک سالن تولید ۴۰ در ۲۰ متری را اندازه‌گیری کنیم. چراغ‌ها حدود ۴ متر بالاتر از سطح کارند. چند نقطه کافی است و در چه ارتفاعی؟',
                answer: [
                    'روشنایی عمومی را با شبکه‌ای از نقاط هم‌فاصله اندازه می‌گیرند و میانگین و کمینه را گزارش می‌کنند. روش رایج تعیین کمینه تعداد نقاط با «شاخص اتاق» است: طول ضرب در عرض، تقسیم بر «ارتفاع چراغ از سطح کار ضرب در مجموع طول و عرض». اگر شاخص کمتر از ۱ باشد دست‌کم ۴ نقطه، از ۱ تا کمتر از ۲ دست‌کم ۹، از ۲ تا کمتر از ۳ دست‌کم ۱۶ و از ۳ به بالا دست‌کم ۲۵ نقطه.',
                    'برای سالن شما: ۸۰۰ تقسیم بر «۴ ضرب در ۶۰» حدود ۳٫۳ است؛ پس دست‌کم ۲۵ نقطه، مثلاً شبکه ۵ در ۵ با نقطه‌ها در مرکز هر خانه. اگر نقاط شبکه با چیدمان چراغ‌ها هم‌گام شوند، تعداد را بیشتر کنید تا نتیجه فقط زیر چراغ‌ها یا فقط بین آنها نباشد.',
                    'اندازه‌گیری در ارتفاع سطح کار انجام می‌شود؛ اگر سطح مشخصی نیست، معمولاً حدود ۰٫۸ متر از کف. لوکس‌متر باید کالیبره و دارای تصحیح کسینوسی و حساسیت طیفی مطابق چشم باشد. چراغ‌ها پیش از قرائت گرم و پایدار شوند، سایه بدن اندازه‌گیر روی حسگر نیفتد و سهم نور روز جداگانه ثبت شود. روشنایی موضعی ایستگاه‌های کار حساس را هم جدا اندازه بگیرید.',
                ],
                sources: ['CIBSE — Code for Lighting', 'IES Lighting Handbook', 'ISO 8995-1:2002'],
            ),
            new EditorialEntry(
                key: 'lighting-screen-glare',
                topic: QuestionTopic::Lighting,
                title: 'بازتاب نور روی مانیتور را چطور کم کنیم؟',
                question: 'کارکنان از بازتاب پنجره و چراغ سقفی روی صفحه نمایش و خستگی چشم شکایت دارند. بدون تعویض کامل سیستم روشنایی چه کار می‌شود کرد؟',
                answer: [
                    'بیشتر بازتاب‌ها با جابه‌جایی حل می‌شوند. صفحه نمایش را طوری بگذارید که پنجره کنار شاغل باشد، نه پشت سرش (بازتاب روی صفحه) و نه روبه‌رویش (خیرگی مستقیم)؛ یعنی خط دید تقریباً موازی پنجره. میز را تا جای ممکن بین ردیف چراغ‌های سقفی بگذارید نه درست زیر آنها، و زاویه صفحه را کمی تغییر دهید تا تصویر چراغ در آن نیفتد.',
                    'پرده یا کرکره قابل تنظیم برای نور روز، صفحه نمایش با سطح مات و چراغ‌هایی با پخش‌کننده یا لوور که در زاویه دید درخشندگی زیاد ندارند، گام‌های بعدی‌اند. ISO 8995-1 برای کار اداری شاخص خیرگی UGR حداکثر ۱۹ را توصیه می‌کند.',
                    'اختلاف زیاد روشنایی بین صفحه و پیرامون هم چشم را خسته می‌کند؛ اتاق را خیلی تاریک نکنید و روشنایی صفحه را با محیط هماهنگ کنید. انجمن بینایی‌سنجی آمریکا قاعده ۲۰-۲۰-۲۰ را پیشنهاد می‌کند: هر ۲۰ دقیقه، ۲۰ ثانیه به فاصله حدود ۶ متر نگاه کنید. اگر شکایت ادامه داشت، معاینه بینایی شاغل را هم در نظر بگیرید.',
                ],
                sources: ['ISO 8995-1:2002', 'OSHA eTool — Computer Workstations: Lighting and Glare', 'American Optometric Association — Computer Vision Syndrome'],
            ),
        ];
    }

    /** @return list<EditorialEntry> */
    private function vibration(): array
    {
        return [
            new EditorialEntry(
                key: 'vibration-hand-arm-a8',
                topic: QuestionTopic::Vibration,
                title: 'مواجهه روزانه با ارتعاش دست و بازو، A(8)، را چطور حساب کنیم؟',
                question: 'یک سنگ‌فرز دستی با شتاب ارتعاش کل ۵ متر بر مجذور ثانیه داریم و اپراتور روزی دو ساعت واقعاً با آن کار می‌کند. مواجهه روزانه‌اش از حد بیشتر است؟',
                answer: [
                    'مواجهه روزانه با ارتعاش دست و بازو با A(8) بیان می‌شود: شتاب معادل انرژی برای ۸ ساعت. A(8) برابر است با شتاب کل (جمع برداری سه محور) ضرب در جذر «مدت مواجهه تقسیم بر ۸ ساعت».',
                    'برای مثال شما: ۵ ضرب در جذر ۲ تقسیم بر ۸، یعنی ۵ ضرب در ۰٫۵، برابر ۲٫۵ متر بر مجذور ثانیه.',
                    'دستورالعمل اروپایی 2002/44/EC مقدار اقدام روزانه را ۲٫۵ و مقدار حدی را ۵ متر بر مجذور ثانیه تعیین کرده است. این اپراتور روی مقدار اقدام است: برنامه کاهش مواجهه (ابزار کم‌ارتعاش، نگهداری ابزار و صفحه سالم، کاهش زمان کار، گرم نگه داشتن دست‌ها) و پایش سلامت لازم است. حد ملاک در ایران را در جدول حدود مجاز وزارت بهداشت هم ببینید.',
                    'مدت مواجهه، زمان واقعی کار با ابزار روشن در دست است، نه کل شیفت. اگر شاغل با چند ابزار کار می‌کند، سهم هر ابزار جدا حساب و با جذر مجموع مربعات ترکیب می‌شود. مقدار اعلام‌شده سازنده در آزمایشگاه به دست آمده و در کار واقعی معمولاً بیشتر است؛ اندازه‌گیری در محل طبق ISO 5349 دقیق‌تر است. ابزار «ارتعاش دست و بازو A(8)» فرابهداشت همین محاسبه را انجام می‌دهد.',
                ],
                sources: ['ISO 5349-1:2001 — Hand-transmitted vibration: General requirements', 'Directive 2002/44/EC of the European Parliament and of the Council (vibration)', 'HSE L140 — Hand-arm vibration'],
            ),
            new EditorialEntry(
                key: 'vibration-whole-body-drivers',
                topic: QuestionTopic::Vibration,
                title: 'ارتعاش تمام بدن رانندگان لودر را چطور ارزیابی کنیم؟',
                question: 'رانندگان لودر و کامیون معدن از کمردرد شکایت دارند. ارتعاش تمام بدن را چطور اندازه بگیریم و با چه حدی مقایسه کنیم؟',
                answer: [
                    'طبق ISO 2631-1، ارتعاش تمام بدن با شتاب‌سنج سه‌محوره روی سطح نشیمن صندلی اندازه‌گیری می‌شود. شتاب هر محور با فیلتر وزن‌دهی فرکانسی حساب می‌شود و برای ارزیابی سلامت، دو محور افقی (جلو-عقب و پهلو به پهلو) در ضریب ۱٫۴ ضرب می‌شوند. محوری که بیشترین مقدار را دارد ملاک است و مانند ارتعاش دست، به مواجهه روزانه A(8) تبدیل می‌شود.',
                    'دستورالعمل 2002/44/EC مقدار اقدام روزانه را ۰٫۵ و مقدار حدی را ۱٫۱۵ متر بر مجذور ثانیه تعیین کرده است. در خودروهای معدنی با ضربه و تکان زیاد، ضریب قله را هم ببینید؛ اگر بیش از ۹ باشد، ISO 2631-1 روش‌های تکمیلی مثل مقدار دوز ارتعاش (VDV) را توصیه می‌کند.',
                    'کنترل‌های مؤثر معمولاً ساده‌اند: نگهداری و هموار کردن مسیر، سرعت متناسب با مسیر، صندلی تعلیق‌دار که با وزن راننده تنظیم شده باشد و نگهداری تعلیق خودرو. کمردرد رانندگان چندعاملی است؛ نشستن طولانی، پیاده و سوار شدن و جابه‌جایی دستی بار را هم در ارزیابی ببینید. ابزار «ارتعاش تمام بدن A(8)» فرابهداشت محاسبه را انجام می‌دهد.',
                ],
                sources: ['ISO 2631-1:1997 — Whole-body vibration: General requirements', 'Directive 2002/44/EC', 'HSE L141 — Whole-body vibration'],
            ),
            new EditorialEntry(
                key: 'vibration-accelerometer-mounting',
                topic: QuestionTopic::Vibration,
                title: 'برای اندازه‌گیری ارتعاش ابزار دستی، شتاب‌سنج را کجا نصب کنیم؟',
                question: 'دستگاه ارتعاش‌سنج با شتاب‌سنج سه‌محوره داریم. برای چکش تخریب برقی، شتاب‌سنج را کجا و چطور ببندیم که نتیجه معتبر باشد؟',
                answer: [
                    'طبق ISO 5349-2، شتاب‌سنج روی دسته ابزار و در محل گرفتن دست، تا جای ممکن نزدیک وسط کف دست نصب می‌شود، بی‌آنکه مانع گرفتن عادی ابزار شود. اگر ابزار با دو دست گرفته می‌شود، هر دسته جدا اندازه‌گیری و مقدار بیشتر ملاک قرار می‌گیرد.',
                    'اتصال باید محکم و سبک باشد (بست مخصوص، آداپتور یا پیچ مناسب)؛ اتصال شل یا سنگین، به‌ویژه در ابزار ضربه‌ای، نتیجه را خراب می‌کند. در ابزار ضربه‌ای مثل چکش تخریب، ضربه شدید می‌تواند در شتاب‌سنج خطای جابه‌جایی صفر (DC shift) ایجاد کند؛ از شتاب‌سنج مناسب ضربه یا فیلتر مکانیکی استفاده کنید و سیگنال را برای نشانه‌های این خطا بررسی کنید.',
                    'مقدار کل، جمع برداری مقدار مؤثر وزن‌دهی‌شده سه محور است. اندازه‌گیری در کار واقعی و با چند تکرار انجام شود و زمان واقعی کار با ابزار جداگانه ثبت شود، چون A(8) هم به شتاب بستگی دارد و هم به زمان. پیش و پس از هر نوبت، زنجیره اندازه‌گیری را با کالیبراتور دستی کنترل کنید.',
                ],
                sources: ['ISO 5349-1:2001', 'ISO 5349-2:2001 — Practical guidance for measurement at the workplace'],
            ),
        ];
    }

    /** @return list<EditorialEntry> */
    private function ergonomics(): array
    {
        return [
            new EditorialEntry(
                key: 'ergonomics-choosing-method',
                topic: QuestionTopic::Ergonomics,
                title: 'برای ارزیابی پوسچر، RULA مناسب است یا REBA یا QEC؟',
                question: 'در یک خط مونتاژ می‌خواهیم خطر اختلالات اسکلتی-عضلانی را ارزیابی کنیم. بعضی کارها نشسته‌اند و بعضی ایستاده با جابه‌جایی جعبه. کدام روش مناسب‌تر است؟',
                answer: [
                    'هر روش برای نوع خاصی از کار ساخته شده است. RULA برای کارهای عمدتاً اندام فوقانی با بدن نسبتاً ثابت (مونتاژ ظریف، کار با رایانه، صندوق) طراحی شده و گردن، تنه و اندام فوقانی را با جزئیات بیشتری می‌بیند. REBA کل بدن را ارزیابی می‌کند و برای پوسچرهای متغیر و کارهایی با جابه‌جایی بار و حرکت پاها مناسب‌تر است. QEC علاوه بر ارزیابی‌گر، نظر خود شاغل را درباره وزن بار، مدت کار و ارتعاش وارد می‌کند و برای غربالگری سریع و پیگیری اثر اقدامات کاربرد دارد. برای بلند کردن و حمل دستی بار، معادله بلند کردن NIOSH یا روش MAC دقیق‌ترند.',
                    'در خط شما، RULA برای ایستگاه‌های نشسته مونتاژ، REBA برای ایستگاه‌های ایستاده و معادله NIOSH برای بلند کردن جعبه‌ها مناسب است. همه این روش‌ها غربالگری‌اند و اولویت اقدام را نشان می‌دهند، نه تشخیص بیماری. پوسچر را در بدترین یا پرتکرارترین لحظه کار ثبت کنید و نتیجه را کنار پرسش‌نامه علائم، مثل پرسش‌نامه نوردیک، ببینید.',
                ],
                sources: ['McAtamney L, Corlett EN. RULA. Applied Ergonomics 1993;24(2)', 'Hignett S, McAtamney L. REBA. Applied Ergonomics 2000;31(2)', 'Li G, Buckle P. QEC. Ergonomics 1999;42(5)', 'HSE — Manual handling assessment charts (MAC)'],
            ),
            new EditorialEntry(
                key: 'ergonomics-niosh-lifting-index',
                topic: QuestionTopic::Ergonomics,
                title: 'نتیجه معادله بلند کردن NIOSH را چطور تفسیر کنیم؟',
                question: 'کارگری کیسه ۲۰ کیلوگرمی را از کف برمی‌دارد و روی میز می‌گذارد. حد وزن توصیه‌شده (RWL) را ۱۱ کیلوگرم به دست آورده‌ایم. این یعنی چه و چه کار کنیم؟',
                answer: [
                    'معادله اصلاح‌شده NIOSH از ثابت بار ۲۳ کیلوگرم شروع می‌کند و آن را در شش ضریب کاهنده ضرب می‌کند: فاصله افقی بار از بدن، ارتفاع شروع، فاصله عمودی جابه‌جایی، زاویه چرخش تنه، تکرار و کیفیت دستگیره. حاصل RWL است: وزنی که تقریباً همه شاغلان سالم بتوانند در همان شرایط برای مدت طولانی بدون افزایش خطر کمردرد بلند کنند.',
                    'شاخص بلند کردن (LI) برابر وزن واقعی تقسیم بر RWL است؛ برای مثال شما ۲۰ تقسیم بر ۱۱، حدود ۱٫۸. LI بیش از ۱ یعنی خطر برای بخشی از شاغلان افزایش یافته و NIOSH یادآوری می‌کند که در LI بیش از ۳ بسیاری از شاغلان در خطر بیشتری هستند. هدف طراحی، LI کمتر از ۱ است.',
                    'مؤثرترین راه، تغییر ضریبی است که بیشترین افت را ایجاد کرده. وقتی بار از کف برداشته می‌شود معمولاً ضریب ارتفاع شروع و فاصله افقی مقصرند؛ بالا آوردن محل برداشت (پالت یا میز بالابر) و نزدیک کردن بار به بدن اغلب بیشترین اثر را دارد. کاهش وزن کیسه یا استفاده از وسیله کمکی هم گزینه‌اند. معادله برای بلند کردن دودستی و روان تعریف شده و برای بلند کردن یک‌دستی، نشسته یا حمل طولانی کاربرد ندارد. ابزار «معادله بلندکردن بار NIOSH» فرابهداشت ضریب‌ها را جدا نشان می‌دهد.',
                ],
                sources: ['Waters TR, Putz-Anderson V, Garg A, Fine LJ. Revised NIOSH equation. Ergonomics 1993;36(7)', 'NIOSH Applications Manual for the Revised NIOSH Lifting Equation, DHHS (NIOSH) 94-110'],
            ),
            new EditorialEntry(
                key: 'ergonomics-computer-workstation',
                topic: QuestionTopic::Ergonomics,
                title: 'میز، صندلی و مانیتور کار با رایانه را چطور تنظیم کنیم؟',
                question: 'کارکنان واحد اداری از گردن‌درد و مچ‌درد شکایت دارند. اصول تنظیم ایستگاه کار با رایانه چیست؟',
                answer: [
                    'از صندلی شروع کنید، چون بقیه به آن وابسته است. ارتفاع صندلی طوری باشد که کف پاها کامل روی زمین یا زیرپایی قرار گیرد و ران‌ها تقریباً افقی باشند؛ پشتی، گودی کمر را حمایت کند. صفحه‌کلید حدود ارتفاع آرنج باشد تا شانه‌ها رها، آرنج حدود ۹۰ درجه یا کمی بازتر و مچ صاف بماند. ماوس کنار صفحه‌کلید و در همان ارتفاع.',
                    'لبه بالایی صفحه نمایش هم‌تراز یا کمی پایین‌تر از سطح چشم و فاصله آن حدود یک طول بازو باشد؛ OSHA دست‌کم ۵۰ سانتی‌متر را پیشنهاد می‌کند. برای کسی که عینک دوکانونی یا چندکانونی دارد، صفحه کمی پایین‌تر باشد تا سر به عقب خم نشود. صفحه روبه‌روی بدن باشد، نه کنار، تا گردن مدام نچرخد.',
                    'مهم‌تر از هر تنظیمی، تغییر وضعیت است: بلند شدن و حرکت کوتاه در فاصله‌های منظم. اگر درد ادامه دارد یا با بی‌حسی همراه است، شاغل به پزشک ارجاع شود؛ این توصیه‌ها جایگزین معاینه نیستند. برای ارزیابی سریع ایستگاه‌های اداری، روش ROSA طراحی شده است.',
                ],
                sources: ['OSHA eTool — Computer Workstations', 'Sonne M, Villalta DL, Andrews DM. ROSA. Applied Ergonomics 2012;43(1)'],
            ),
        ];
    }

    /** @return list<EditorialEntry> */
    private function statistics(): array
    {
        return [
            new EditorialEntry(
                key: 'statistics-number-of-samples',
                topic: QuestionTopic::ExposureStatistics,
                title: 'برای قضاوت درباره رعایت حد مجاز چند نمونه لازم است؟',
                question: 'برای یک گروه مواجهه مشابه از جوشکاران فقط یک نمونه شخصی گرفته‌ایم که ۴۰ درصد حد مجاز است. می‌توانیم بگوییم مواجهه قابل قبول است؟',
                answer: [
                    'با یک نمونه نه. مواجهه شغلی از روزی به روز دیگر تغییر زیادی دارد و معمولاً از توزیع لگ‌نرمال پیروی می‌کند؛ یک نتیجه ۴۰ درصدی می‌تواند از گروهی آمده باشد که بخش قابل توجهی از روزهایش بالای حد است.',
                    'استاندارد EN 689:2018 یک آزمون اولیه ساده دارد: با ۳ نمونه اگر همه کمتر از ۱۰ درصد حد مجاز باشند، با ۴ نمونه همه کمتر از ۱۵ درصد، یا با ۵ نمونه همه کمتر از ۲۰ درصد، رعایت حد پذیرفته می‌شود. اگر نتیجه‌ای بالای حد باشد، رعایت نشده است. در غیر این دو حالت دست‌کم ۶ نمونه لازم است و آزمون آماری: باید با اطمینان ۷۰ درصد نشان داد که کمتر از ۵ درصد مواجهه‌ها از حد مجاز بیشترند.',
                    'نمونه‌ها باید در روزها و شیفت‌های مختلف و از افراد مختلف گروه گرفته شوند، نه همه در یک روز. با نتیجه ۴۰ درصدی، احتمالاً به آزمون آماری با ۶ نمونه یا بیشتر نیاز دارید.',
                ],
                sources: ['EN 689:2018+AC:2019 — Workplace exposure: Measurement of exposure by inhalation to chemical agents', 'AIHA — A Strategy for Assessing and Managing Occupational Exposures, 4th ed.'],
            ),
            new EditorialEntry(
                key: 'statistics-lognormal-gm-gsd',
                topic: QuestionTopic::ExposureStatistics,
                title: 'چرا در آمار مواجهه میانگین هندسی و انحراف معیار هندسی گزارش می‌شود؟',
                question: 'نتایج ۸ نمونه گرد و غبار را داریم. مشاور گفته میانگین حسابی کافی نیست و باید میانگین هندسی، انحراف معیار هندسی و صدک ۹۵ گزارش کنیم. چرا؟',
                answer: [
                    'داده‌های مواجهه شغلی معمولاً چوله به راست‌اند: بیشتر روزها پایین و چند روز خیلی بالا. توزیع لگ‌نرمال این رفتار را خوب توصیف می‌کند و در آن میانگین هندسی (GM) معیار مرکز و انحراف معیار هندسی (GSD) معیار پراکندگی است. GSD نزدیک ۱٫۵ یعنی تغییرپذیری کم؛ GSD بیش از ۳ نشان می‌دهد گروه احتمالاً همگن نیست یا عامل تغییردهنده‌ای دارد و تعریف گروه باید بازبینی شود.',
                    'پرسش اصلی این است که چه سهمی از روزها از حد مجاز بیشتر است، نه اینکه میانگین زیر حد است یا نه. به همین دلیل AIHA و EN 689 صدک ۹۵ را با حد مجاز مقایسه می‌کنند. صدک ۹۵ برابر است با GM ضرب در GSD به توان ۱٫۶۴۵. با تعداد کم نمونه، حد بالای تحمل (UTL) صدک ۹۵ هم گزارش می‌شود تا عدم قطعیت ناشی از کمی نمونه دیده شود.',
                    'میانگین حسابی بی‌فایده نیست و برای اثرهای مزمن و برآورد دوز تجمعی کاربرد دارد. پیش از این محاسبه‌ها، برازش لگ‌نرمال را با نمودار احتمال یا آزمون شاپیرو-ویلک روی لگاریتم داده‌ها بررسی کنید.',
                ],
                sources: ['AIHA — A Strategy for Assessing and Managing Occupational Exposures, 4th ed.', 'EN 689:2018', 'Leidel NA, Busch KA, Lynch JR. NIOSH Occupational Exposure Sampling Strategy Manual, 1977'],
            ),
            new EditorialEntry(
                key: 'statistics-below-detection-limit',
                topic: QuestionTopic::ExposureStatistics,
                title: 'با نتایج کمتر از حد تشخیص (LOD) چه کنیم؟',
                question: 'از ۱۰ نمونه بنزن، ۴ نتیجه «کمتر از حد تشخیص» گزارش شده است. این‌ها را صفر بگذاریم یا از محاسبه حذف کنیم؟',
                answer: [
                    'هیچ‌کدام. صفر گذاشتن مواجهه را کمتر از واقع و حذف کردن آن را بیشتر از واقع نشان می‌دهد. روش ساده جانشینی رایج است: طبق پیشنهاد هورنانگ و رید، اگر داده‌ها خیلی چوله نیستند (GSD کمتر از ۳) مقدار LOD تقسیم بر جذر ۲ و اگر چوله‌ترند LOD تقسیم بر ۲ جانشین شود. این روش وقتی سهم نتایج زیر LOD کم است قابل قبول است.',
                    'با ۴ از ۱۰ (۴۰ درصد)، روش‌های ویژه داده‌های سانسورشده مناسب‌ترند: برآورد بیشینه درست‌نمایی، رگرسیون روی آماره‌های ترتیبی (ROS) یا روش‌های بیزی مثل آنچه در Expostats به کار رفته است.',
                    'در گزارش، تعداد نتایج زیر LOD و روش برخورد با آنها را صریح بنویسید. اگر LOD آزمایشگاه نسبت به حد مجاز بالاست، که برای بنزن با حد مجاز پایین محتمل است، درباره حجم نمونه بیشتر یا روش حساس‌تر با آزمایشگاه هماهنگ کنید؛ وگرنه «کمتر از LOD» اطلاعات کمی می‌دهد.',
                ],
                sources: ['Hornung RW, Reed LD. Estimation of average concentration in the presence of nondetectable values. Appl Occup Environ Hyg 1990;5(1)', 'Helsel DR. Statistics for Censored Environmental Data Using Minitab and R, 2012', 'Lavoué J, et al. Expostats. Ann Work Expo Health 2019;63(3)'],
            ),
        ];
    }

    /** @return list<EditorialEntry> */
    private function management(): array
    {
        return [
            new EditorialEntry(
                key: 'management-hierarchy-of-controls',
                topic: QuestionTopic::SafetyManagement,
                title: 'چرا وسیله حفاظت فردی آخرین گزینه کنترل است؟',
                question: 'مدیر کارخانه می‌گوید برای صدای سالن پرس فقط گوشی حفاظتی بدهیم چون ارزان‌تر است. چطور توضیح بدهم که این کافی نیست؟',
                answer: [
                    'سلسله‌مراتب کنترل که NIOSH و ISO 45001 هر دو بر آن تکیه دارند، به ترتیب اثربخشی این است: حذف خطر، جایگزینی با گزینه کم‌خطرتر، کنترل مهندسی (جدا کردن شاغل از خطر)، کنترل مدیریتی (روش کار، آموزش، کاهش زمان) و در آخر وسایل حفاظت فردی.',
                    'حفاظ فردی آخر است چون اثرش به رفتار هر نفر در هر لحظه بستگی دارد: درست گذاشتن، استفاده در تمام مدت، سالم بودن و تعویض به‌موقع. چند دقیقه برداشتن گوشی در محیط پرصدا بخش بزرگی از حفاظت آن روز را از بین می‌برد. کنترل مهندسی یک بار اجرا می‌شود و برای همه و همیشه کار می‌کند.',
                    'برای قانع کردن مدیر، هزینه را در کل عمر مقایسه کنید: خرید و تعویض دائمی حفاظ، آموزش، نظارت، ادیومتری دوره‌ای و پیامدهای افت شنوایی، در برابر هزینه یک‌باره محفظه، عایق یا اصلاح منبع صدا. این به معنای کنار گذاشتن گوشی نیست؛ تا اجرای کنترل‌های بالاتر و برای مواجهه باقی‌مانده لازم است.',
                ],
                sources: ['NIOSH — Hierarchy of Controls', 'ISO 45001:2018, clause 8.1.2 — Eliminating hazards and reducing OH&S risks'],
            ),
